require_once __DIR__.'/../includes/functions.php';require_role(['super_admin']);$db=db();$users=(int)$db->query('SELECT COUNT(*) FROM users')->fetchColumn();$doctors=(int)$db->query('SELECT COUNT(*) FROM doctors')->fetchColumn();$patients=(int)$db->query('SELECT COUNT(*) FROM patients')->fetchColumn();$logs=$db->query('SELECT al.*,u.name user_name FROM audit_logs al LEFT JOIN users u ON u.id=al.user_id ORDER BY al.created_at DESC LIMIT 8')->fetchAll();$pageTitle='Super admin overview';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/page.php';page_heading('System administration','System overview','Global user access, clinic activity and security monitoring.','<a class="btn btn-primary" href="'.e(url('users/index.php')).'"><i class="bi bi-person-plus me-1"></i>Manage users</a>');?>
<div class="row g-3 mb-4"><div class="col-6 col-xl-3"><?=stat_card('User accounts',(string)$users,'people','All system roles')?></div><div class="col-6 col-xl-3"><?=stat_card('Doctors',(string)$doctors,'person-badge','Clinical team')?></div><div class="col-6 col-xl-3"><?=stat_card('Patients',(string)$patients,'people-fill','Patient profiles')?></div><div class="col-6 col-xl-3"><?=stat_card('Audit events',(string)$db->query('SELECT COUNT(*) FROM audit_logs')->fetchColumn(),'shield-check','Logged system activity')?></div></div><div class="card"><div class="card-header d-flex justify-content-between"><h2 class="section-title">Recent audit activity</h2><a class="small text-decoration-none" href="<?=e(url('reports/audit-logs.php'))?>">View audit logs</a></div><div class="table-responsive"><table class="table"><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Entity</th><th>Details</th></tr></thead><tbody><?php foreach($logs as $l):?><tr><td><?=e($l['created_at'])?></td><td><?=e($l['user_name']??'System')?></td><td><span class="badge text-bg-light border"><?=e($l['action'])?></span></td><td><?=e($l['entity_type'])?> <?=e($l['entity_id'])?></td><td><?=e($l['metadata'])?></td></tr><?php endforeach;?><?php if(!$logs)echo empty_row(5);?></tbody></table></div></div><?php require __DIR__.'/../includes/footer.php';?>